export function multiplier(db,level){if(level<1||level>51||level*2%1)throw Error('레벨은 1–51, 0.5 단위입니다.');const n=Math.floor(level)-1;return Number.isInteger(level)?db.cpm[n]:Math.sqrt((db.cpm[n]**2+db.cpm[n+1]**2)/2);}
export function stats(db,p,iv,level){if(iv.length!==3||iv.some(x=>!Number.isInteger(x)||x<0||x>15))throw Error('IV는 0–15 정수입니다.');const m=multiplier(db,level),a=(p.stats.atk+iv[0])*m,d=(p.stats.def+iv[1])*m,h=Math.max(10,Math.floor((p.stats.hp+iv[2])*m));return {a,d,h,cp:Math.max(10,Math.floor((p.stats.atk+iv[0])*Math.sqrt(p.stats.def+iv[1])*Math.sqrt(p.stats.hp+iv[2])*m*m/10)),product:a*d*h};}
export function best(db,p,iv,cap,max){let lo=2,hi=max*2,win=null;while(lo<=hi){const mid=Math.floor((lo+hi)/2),s=stats(db,p,iv,mid/2);if(s.cp<=cap){win={...s,level:mid/2};lo=mid+1}else hi=mid-1}return win;}
const cache=new Map();
export function league(db,p,iv,cap,max=50){const key=[db.sha256?.[0],p.id,cap,max].join('|');let all=cache.get(key);if(!all){all=[];for(let a=0;a<16;a++)for(let d=0;d<16;d++)for(let h=0;h<16;h++){const s=best(db,p,[a,d,h],cap,max);if(s)all.push({iv:[a,d,h],...s});}all.sort((a,b)=>b.product-a.product);cache.set(key,all)}const s=best(db,p,iv,cap,max);if(!s||!all.length)return null;const rank=1+all.filter(x=>x.product>s.product+1e-7).length;return {...s,rank,total:4096,eligible:all.length,percent:s.product/all[0].product*100,percentile:(4096-rank)/4095*100,best:all[0].iv};}
// Type interactions: immune interactions in GO use 0.390625, not zero.
const chart={normal:[[],['rock','steel'],['ghost']],fire:[['grass','ice','bug','steel'],['fire','water','rock','dragon'],[]],water:[['fire','ground','rock'],['water','grass','dragon'],[]],electric:[['water','flying'],['electric','grass','dragon'],['ground']],grass:[['water','ground','rock'],['fire','grass','poison','flying','bug','dragon','steel'],[]],ice:[['grass','ground','flying','dragon'],['fire','water','ice','steel'],[]],fighting:[['normal','ice','rock','dark','steel'],['poison','flying','psychic','bug','fairy'],['ghost']],poison:[['grass','fairy'],['poison','ground','rock','ghost'],['steel']],ground:[['fire','electric','poison','rock','steel'],['grass','bug'],['flying']],flying:[['grass','fighting','bug'],['electric','rock','steel'],[]],psychic:[['fighting','poison'],['psychic','steel'],['dark']],bug:[['grass','psychic','dark'],['fire','fighting','poison','flying','ghost','steel','fairy'],[]],rock:[['fire','ice','flying','bug'],['fighting','ground','steel'],[]],ghost:[['psychic','ghost'],['dark'],['normal']],dragon:[['dragon'],['steel'],['fairy']],dark:[['psychic','ghost'],['fighting','dark','fairy'],[]],steel:[['ice','rock','fairy'],['fire','water','electric','steel'],[]],fairy:[['fighting','dragon','dark'],['fire','poison','steel'],[]]};
export function effectiveness(type,defenders){return defenders.reduce((n,t)=>{const c=chart[type];return n*(c?.[0].includes(t)?1.6:c?.[1].includes(t)?.625:c?.[2].includes(t)?.390625:1)},1);}
export function raidDps(db,p,iv,level,shadow,fast,charged,target){const f=db.moves[fast],c=db.moves[charged];if(!f||!c||f.energy<=0||c.energy>=0||!p.fast.includes(fast)||!p.charged.includes(charged)||shadow&&p.mega)return null;const s=stats(db,p,iv,level),damage=m=>Math.floor(.5*m.power*s.a/target.defense*(p.types.includes(m.type)?1.2:1)*effectiveness(m.type,target.types)*(shadow?1.2:1))+1,n=Math.ceil(-c.energy/f.energy);return (n*damage(f)+damage(c))/(n*f.seconds+c.seconds);}
export function raid(db,p,iv,level,shadow,fast,charged,target){const dps=raidDps(db,p,iv,level,shadow,fast,charged,target);if(dps===null)return null;let top=0;for(const q of db.pokemon){for(const f of q.fast)for(const c of q.charged){if(['FRUSTRATION','RETURN'].includes(c))continue;for(const sh of q.mega?[false]:[false,true])top=Math.max(top,raidDps(db,q,[15,15,15],40,sh,f,c,target)||0)}}const percent=dps/top*100;return {dps,percent,tier:percent>=95?'S':percent>=85?'A':percent>=70?'B':percent>=55?'C':'D',top};}
